// Post-match breakdown, generated by fixed rules from the stored match data after
// every game. Measured facts and rule-based interpretation are kept in separate fields.
import { round } from './stats.js';

const f2 = (v) => (v === null || v === undefined ? '—' : Number(v).toFixed(2));
const f1 = (v) => (v === null || v === undefined ? '—' : Number(v).toFixed(1));
const SIT = { regular: 'open play', assisted: 'open play (assisted)', 'fast-break': 'a fast break', 'set-piece': 'a set piece', corner: 'a corner', 'free-kick': 'a direct free kick', penalty: 'a penalty', 'throw-in-set-piece': 'a throw-in routine' };

export function matchBreakdown({ match, teamSummary, seasonPlayers }) {
  const f = match.fixture; const d = match.detail; const t = match.team;
  if (!f.score) return null;
  const opp = f.opponent;
  const out = { headline: null, verdict: null, moments: [], spells: [], style: [], styleTags: [], halves: null, comparison: [], players: [], standouts: [], howSpursPlayed: [], sources: [] };

  // ---- Headline and verdict ----
  const xgF = d?.spurs?.xg ?? t?.xg; const xgA = d?.opp?.xg ?? t?.xga;
  out.headline = `${f.home ? 'Spurs' : opp} ${f.home ? f.score.spurs : f.score.opp}–${f.home ? f.score.opp : f.score.spurs} ${f.home ? opp : 'Spurs'}`;
  if (xgF !== null && xgF !== undefined && xgA !== null && xgA !== undefined) {
    const diff = xgF - xgA;
    const fair = Math.abs(diff) < 0.35 ? 'D' : diff > 0 ? 'W' : 'L';
    out.verdict = {
      xgFor: round(xgF, 2), xgAgainst: round(xgA, 2), result: f.result, xgResult: fair,
      text: fair === f.result ? `The result matched the chances: ${f2(xgF)} xG to ${f2(xgA)}.`
        : fair === 'W' ? `Spurs created the better chances (${f2(xgF)} xG to ${f2(xgA)}) and deserved more than a ${f.result === 'D' ? 'draw' : 'defeat'}.`
          : fair === 'L' ? `${opp} created the better chances (${f2(xgA)} xG to ${f2(xgF)}); Spurs ${f.result === 'W' ? 'won despite that' : 'were fortunate to draw'}.`
            : `Chances were even (${f2(xgF)} xG to ${f2(xgA)}), so the ${f.result === 'W' ? 'win' : 'defeat'} came down to finishing and fine margins.`,
    };
  }

  // ---- Key moments (from shot data, with minutes) ----
  const shots = (d?.shots || []).map((s) => ({ ...s }));
  // The shot feed sometimes lacks the shooter; fill unattributed goals from the FPL
  // scorer list for that side (only when the count leaves no ambiguity about order).
  for (const side of ['spurs', 'opp']) {
    const scorers = [];
    for (const e of (f.events || []).filter((x) => x.type === 'goal' && x.team === side)) for (let i = 0; i < (e.value || 1); i++) scorers.push(e.player);
    const named = shots.filter((s) => s.team === side && s.outcome === 'goal' && s.player).map((s) => s.player);
    for (const n of named) { const i = scorers.indexOf(n); if (i >= 0) scorers.splice(i, 1); }
    const unnamed = shots.filter((s) => s.team === side && s.outcome === 'goal' && !s.player);
    if (unnamed.length && new Set(scorers).size === 1) for (const s of unnamed) s.player = `${scorers[0]}`;
  }
  for (const s of shots) {
    if (s.minute === null) continue;
    const who = s.player || (s.team === 'spurs' ? 'A Spurs player' : `${opp} player`);
    const side = s.team;
    const min = `${s.minute}${s.added ? `+${s.added}` : ''}'`;
    if (s.outcome === 'goal') out.moments.push({ minute: s.minute, label: min, side, kind: 'goal', text: `Goal: ${who} from ${SIT[s.situation] || 'open play'} (xG ${f2(s.xg)})` });
    else if ((s.xg || 0) >= 0.3) out.moments.push({ minute: s.minute, label: min, side, kind: 'big-chance', text: `Big chance ${s.outcome === 'save' ? 'saved' : s.outcome === 'block' ? 'blocked' : 'missed'}: ${who} (xG ${f2(s.xg)})` });
    else if (s.outcome === 'post') out.moments.push({ minute: s.minute, label: min, side, kind: 'woodwork', text: `Hit the woodwork: ${who}` });
  }
  out.moments.sort((a, b) => a.minute - b.minute);

  // ---- Spells of pressure (from the momentum index) ----
  const mom = d?.momentum || [];
  if (mom.length > 20) {
    const maxAbs = Math.max(...mom.map((m) => Math.abs(m.value)), 1);
    let run = null;
    const close = () => { if (run && run.end - run.start >= 6 && run.peak >= maxAbs * 0.45) out.spells.push({ side: run.side, from: run.start, to: run.end, text: `${run.side === 'spurs' ? 'Spurs' : opp} on top, ${run.start}–${run.end}'` }); run = null; };
    for (const m of mom) {
      const side = m.value > 0 ? 'spurs' : m.value < 0 ? 'opp' : null;
      if (!side) continue;
      if (run && run.side === side && m.minute - run.end <= 2) { run.end = m.minute; run.peak = Math.max(run.peak, Math.abs(m.value)); } else { close(); run = { side, start: m.minute, end: m.minute, peak: Math.abs(m.value) }; }
    }
    close();
    const sp = mom.filter((m) => m.value > 0).length; const op = mom.filter((m) => m.value < 0).length;
    out.momentumShare = sp + op ? round((sp / (sp + op)) * 100, 0) : null;
  }

  // ---- Style of play ----
  const S = d?.spurs; const O = d?.opp;
  const season = teamSummary?.overall?.adv?.perMatch;
  const league = teamSummary?.leagueRanks?.metrics || {};
  if (S && O) {
    const tilt = S.oppHalf !== null && O.oppHalf !== null && S.oppHalf + O.oppHalf > 0 ? (S.oppHalf / (S.oppHalf + O.oppHalf)) * 100 : null;
    const longShare = S.longBallsAcc !== null && S.passesAcc ? (S.longBallsAcc / S.passesAcc) * 100 : null;
    const xgPerShot = S.xg !== null && S.shots ? S.xg / S.shots : null;
    const outsideShare = S.shotsOutBox !== null && S.shots ? (S.shotsOutBox / S.shots) * 100 : null;
    const setShare = S.xgSetPlay !== null && S.xg ? (S.xgSetPlay / S.xg) * 100 : null;
    const row = (label, value, unit, seasonAvg, leagueAvg, dp = 1) => ({ label, value: value === null ? null : round(value, dp), unit, seasonAvg: seasonAvg ?? null, leagueAvg: leagueAvg ?? null });
    out.style = [
      row('Possession', S.possession, '%', season?.possession?.spurs?.value, league.possession?.leagueAvg),
      row('Field tilt (share of passes in opposition half)', tilt, '%', season?.fieldTilt?.value ?? null, league.fieldTilt?.leagueAvg),
      row('Pass accuracy', S.passPct, '%', season?.passPct?.spurs?.value, league.passPct?.leagueAvg),
      row('Long balls as share of accurate passes', longShare, '%', null, null),
      row('Shots', S.shots, '', season?.shots?.spurs?.value, league.shots?.leagueAvg, 0),
      row('xG per shot (chance quality)', xgPerShot, '', null, null, 3),
      row('Shots from outside the box', outsideShare, '%', null, null),
      row('Successful take-ons', S.dribbles, '', season?.dribbles?.spurs?.value, league.dribbles?.leagueAvg, 0),
      row('Share of xG from set plays', setShare, '%', null, null),
    ];
    const tags = [];
    if (S.possession >= 58) tags.push('Dominated the ball'); else if (S.possession <= 42) tags.push('Played without the ball');
    if (tilt !== null && tilt >= 62) tags.push('Pinned the opponent back'); else if (tilt !== null && tilt <= 40) tags.push('Pushed back');
    if (longShare !== null && longShare >= 9) tags.push('Direct, long-ball heavy'); else if (longShare !== null && longShare <= 5) tags.push('Short, patient passing');
    if (xgPerShot !== null && xgPerShot < 0.08 && S.shots >= 8) tags.push('Lots of low-quality shots'); else if (xgPerShot !== null && xgPerShot >= 0.15) tags.push('Worked high-quality chances');
    if (outsideShare !== null && outsideShare >= 50) tags.push('Shot from distance');
    if (setShare !== null && setShare >= 40 && S.xg >= 0.3) tags.push('Relied on set pieces');
    if (S.dribbles !== null && league.dribbles && S.dribbles >= league.dribbles.leagueAvg * 1.4) tags.push('Took players on');
    out.styleTags = tags;

    // Team numbers against Spurs' own season average.
    const cmp = (label, a, b, avgSpurs, lowerBetter = false, dp = 0) => ({ label, spurs: a, opp: b, seasonAvg: avgSpurs ?? null, lowerBetter, dp });
    out.comparison = [
      cmp('xG', S.xg, O.xg, season?.xg?.spurs?.value ?? null, false, 2), cmp('Shots', S.shots, O.shots, season?.shots?.spurs?.value), cmp('Shots on target', S.sot, O.sot, season?.sot?.spurs?.value),
      cmp('Big chances', S.bigChances, O.bigChances, season?.bigChances?.spurs?.value), cmp('Possession %', S.possession, O.possession, season?.possession?.spurs?.value),
      cmp('Passes', S.passes, O.passes, season?.passes?.spurs?.value, false, 0), cmp('Pass accuracy %', S.passPct, O.passPct, season?.passPct?.spurs?.value),
      cmp('Touches in opposition box', S.touchesOppBox, O.touchesOppBox, season?.touchesOppBox?.spurs?.value), cmp('Successful take-ons', S.dribbles, O.dribbles, season?.dribbles?.spurs?.value),
      cmp('Tackles won', S.tacklesWon, O.tacklesWon, season?.tacklesWon?.spurs?.value), cmp('Interceptions', S.interceptions, O.interceptions, season?.interceptions?.spurs?.value),
      cmp('Clearances', S.clearances, O.clearances, season?.clearances?.spurs?.value), cmp('Aerial duels won %', S.aerialPct, O.aerialPct, season?.aerialPct?.spurs?.value),
      cmp('Corners', S.corners, O.corners, season?.corners?.spurs?.value), cmp('Fouls', S.fouls, O.fouls, null, true, 0), cmp('Saves', S.saves, O.saves, null, false, 0),
    ];
  }

  // ---- Halves ----
  if (shots.length) {
    const h = { first: { gf: 0, ga: 0, xgf: 0, xga: 0, shotsF: 0, shotsA: 0 }, second: { gf: 0, ga: 0, xgf: 0, xga: 0, shotsF: 0, shotsA: 0 } };
    for (const s of shots) {
      if (s.minute === null || s.minute > 90) continue;
      const b = h[s.minute <= 45 ? 'first' : 'second'];
      if (s.team === 'spurs') { b.shotsF++; b.xgf += s.xg || 0; if (s.outcome === 'goal') b.gf++; } else { b.shotsA++; b.xga += s.xg || 0; if (s.outcome === 'goal') b.ga++; }
    }
    for (const b of Object.values(h)) { b.xgf = round(b.xgf, 2); b.xga = round(b.xga, 2); }
    out.halves = h;
  }

  // ---- Players ----
  const seasonById = new Map((seasonPlayers || []).map((p) => [p.id, p]));
  const lineup = match.lineup || [];
  const per90 = (v, m) => (v === null || v === undefined || !m ? null : (v / m) * 90);
  for (const l of lineup) {
    const sp = seasonById.get(l.playerId);
    const notes = [];
    const vsSeason = (k, label, min = 0.5) => {
      const s90 = sp?.season?.per90?.[k]; const m90 = per90(l[k], l.minutes);
      if (s90 === null || s90 === undefined || m90 === null || l.minutes < 45 || s90 < min * 0.2) return;
      if (m90 >= s90 * 1.6 && l[k] >= min) notes.push(`more ${label} than usual`);
      if (m90 <= s90 * 0.4 && s90 >= min) notes.push(`fewer ${label} than usual`);
    };
    if (l.pos !== 'GK') { vsSeason('chancesCreated', 'chances created', 1); vsSeason('shots', 'shots', 1); vsSeason('recoveries', 'recoveries', 3); vsSeason('tacklesWon', 'tackles won', 1); vsSeason('touches', 'touches', 20); }
    const key = l.pos === 'GK'
      ? [['Saves', l.gkSaves ?? l.saves], ['Goals prevented', l.goalsPrevented, 2], ['Conceded', l.gc], ['Passes', l.passesAcc]]
      : [['G+A', (l.goals || 0) + (l.assists || 0)], ['xG', l.xg, 2], ['xA', l.xa, 2], ['Shots', l.shots], ['Chances', l.chancesCreated], ['Passes', l.passesAcc], ['Box touches', l.touchesBox], ['Tackles won', l.tacklesWon], ['Interceptions', l.interceptions], ['Recoveries', l.recoveries], ['Duels', l.duelsWon !== null && l.duelsLost !== null ? `${l.duelsWon}/${l.duelsWon + l.duelsLost}` : null]];
    out.players.push({ playerId: l.playerId, name: l.name, pos: l.pos, role: l.role, minutes: l.minutes, goals: l.goals, assists: l.assists, key: key.filter(([, v]) => v !== null && v !== undefined).map(([k, v, dp]) => [k, typeof v === 'number' && dp ? round(v, dp) : v]), notes, points: l.points });
  }
  const best = (label, fn, fmt = (v) => v) => {
    const c = lineup.map((l) => ({ l, v: fn(l) })).filter((x) => x.v !== null && x.v !== undefined && x.v > 0).sort((a, b) => b.v - a.v)[0];
    if (c) out.standouts.push({ label, name: c.l.name, playerId: c.l.playerId, value: fmt(c.v) });
  };
  best('Most dangerous (xG + xA)', (l) => (l.xg === null ? null : l.xg + (l.xa || 0)), (v) => f2(v));
  best('Chances created', (l) => l.chancesCreated);
  best('Most passes completed', (l) => l.passesAcc);
  best('Final-third passes', (l) => l.finalThirdPasses);
  best('Ball-winner (tackles won + interceptions)', (l) => (l.tacklesWon === null && l.interceptions === null ? null : (l.tacklesWon || 0) + (l.interceptions || 0)));
  best('Recoveries', (l) => (l.pos === 'GK' ? null : l.recoveries));
  best('Duels won', (l) => l.duelsWon);
  best('Touches in the box', (l) => l.touchesBox);

  // ---- How Spurs played (rule-based narrative) ----
  const say = (x) => out.howSpursPlayed.push(x);
  if (S && O) {
    const tilt = out.style[1]?.value;
    say(`Spurs had ${f1(S.possession)}% of the ball${tilt !== null ? ` and ${f1(tilt)}% of the passing in the opposition half` : ''}${season?.possession?.spurs?.value ? `, against a season average of ${f1(season.possession.spurs.value)}%` : ''}.`);
    if (S.shots !== null) say(`They took ${S.shots} shots (${S.sot ?? '—'} on target) worth ${f2(S.xg)} xG${S.shots ? `, about ${f2(S.xg / S.shots)} per shot` : ''}; ${opp} had ${O.shots} shots worth ${f2(O.xg)}.`);
    if (out.halves) {
      const a = out.halves.first; const b = out.halves.second;
      const d1 = a.xgf - a.xga; const d2 = b.xgf - b.xga;
      if (Math.abs(d2 - d1) >= 0.5) say(`The match changed after half-time: Spurs' xG difference went from ${d1 >= 0 ? '+' : ''}${d1.toFixed(2)} in the first half to ${d2 >= 0 ? '+' : ''}${d2.toFixed(2)} in the second.`);
    }
    if (out.spells.length) say(`Momentum: ${out.spells.map((s) => s.text).join('; ')}.`);
    if (out.styleTags.length) say(`In short: ${out.styleTags.join(', ').toLowerCase()}.`);
  } else if (t) {
    say(`Spurs produced ${f2(t.xg)} xG and allowed ${f2(t.xga)} (FPL/Opta). Detailed match statistics are not available for this match.`);
  }
  out.sources = [match.source, d ? 'FPL Core Insights (FotMob match data): shots, minutes, momentum, team and player match stats' : null].filter(Boolean);
  out.label = 'Generated automatically after the match by fixed rules from the stored data. Interpretation is calculated, not an expert opinion.';
  return out;
}
